INSERT INTO "intangible_heritage_items" ("id", "village_id", "name", "recognition_level", "uniqueness_description", "participation_scope", "generations_transmitted", "tourist_experience_level", "event_timing", "capacity_note", "media_ids", "created_at", "updated_at")
VALUES
  ('4db72c36-f46c-41ef-ae97-b2151dba097f', '01000000-0000-0000-0000-000000000001', 'Hội làng', NULL, 'Ngày 13 tháng giêng tổ chức vật thờ tại đình, đây cũng là nguồn gốc tên đình Vật. Ngày 14 tháng giêng ra đình dâng lễ. Tế ở miếu (nới thờ 2 vị Thành Hoàng làng), sau đó phụng nghênh Thánh giá xuống đình, Thánh giá đi qua cửa miếu sang cửa chùa sau đó rước xuống đình Vật . Từ ngày 15 diễn ra tế lễ thành hoàng vào sáng và chiều, xen vào là các hoạt động văn hóa thể thao, buổi tối hát cửa đình, chèo. Hội diễn ra 3 hoặc 5 ngày, ngày cuối làm lễ rước Thánh về miếu.', 'toan_the_cong_dong', 'hơn 3 thế hệ (cụ kị/  tổ tiên - ông bà - bố mẹ -con cháu) — từ lâu đời', 'trai_nghiem_mot_phan', 'tổ chức ngày 14/1 hàng năm làm lễ dâng hương ở đình. Cứ 2 hoặc 5 năm thì làm lễ lớn, rước thánh từ miếu qua cổng chùa rồi đến Đình Vực, lễ 3 hoặc 5 ngày, ngày cuối rước Thánh về miếu', 'khoảng 1000 người', NULL, '2026-09-21T07:18:17.766Z', '2026-09-21T07:18:17.766Z'),
  ('e21d9719-b541-4608-9fe5-8b93fb79c662', '01000000-0000-0000-0000-000000000001', 'Ẩm thực truyền thống: làm miến', NULL, 'Miến làng Cự đà làm 100% bằng bột dong riềng, bột dong riềng phơi khô là tốt nhất. Dong riềng lấy từ các vùng như Bắc Kan, Lai Châu, Sơn La, Mộc Châu,… Bột dong riềng được ngâm với nước và lọc để chọn phần tinh bột, rồi đánh lên. Một phần bột được ngâm với nước sôi gọi là bột chin. Bột chin mang hòa với bột đã lọc, với tỷ lệ 1/10 tạo nên hỗn hợp. Tiếp đó, bột được tráng thành bánh, hấp chin, đem phơi nắng. Sau khi gần khô, bánh được đưa qua máy cán thành từng sợi miến nhỏ, dài và phơi nắng tiếp là thành miến thành phẩm. 
 Hiện phơi miến ở bãi ngoài làng', 'toan_the_cong_dong', '3 thế hệ (ông bà - bố mẹ - con cháu) — 3 thế hệ, khoảng từ 1950-1960', 'chi_xem', NULL, NULL, NULL, '2026-09-21T07:18:17.766Z', '2026-09-21T07:18:17.766Z'),
  ('e81a43b9-ebd8-4d8c-b739-4ca33360e050', '01000000-0000-0000-0000-000000000001', 'Ẩm thực truyền thống: làm tương', NULL, 'Từ hàng trăm năm nay với câu ca danh truyền “Tương Cự Đà, cà làng Đám".Nguyên liệu để làm tương gồm gạo nếp, muối, đậu tương và nước sạch, làm nước mưa thì ngon hơn. Đối với gạo, phải chọn loại gạo nếp cái hoa vàng, là giống gạo nếp truyền thống nổi tiếng tại các tỉnh đồng bằng và trung du Bắc Bộ, có hạt gạo tròn, dẻo, thơm. Đậu tương cũng phải là đậu tương leo, khi chin hạt vẫn nhỏ và có màu vàng nhạt. Tương ngon phụ thuộc chính vào khâu làm mốc. Khi mốc đã vàng, đậu tương rang đã tróc vỏ thì phải ngâm cho hạt đậu ngập đủ nước, cộng thêm một lượng men rồi đem ủ kín trong bể. Khi mở bể cũng là lúc người làm phải khéo léo đảo sao cho tương phải đều, phải quyện, bao giờ thấy tương giống như loại bột lỏng thì coi như được.
Xưa kia chỉ người giàu mới mua được Tương Cự Đà và 1 năm làng cũng chỉ làm 1 vụ', 'toan_the_cong_dong', 'hơn 3 thế hệ (cụ kị/  tổ tiên - ông bà - bố mẹ -con cháu) — có lịch sử từ hàng trăm năm', 'chi_xem', NULL, NULL, NULL, '2026-09-21T07:18:17.766Z', '2026-09-21T07:18:17.766Z'),
  ('3e527667-a74f-4430-9363-008103516095', 'fdd98e46-3b65-490d-aadc-dbb90eab321d', 'Ngữ văn dân gian (chuyện kể, thần thoại, cổ tích…)', NULL, 'Làng Hạ Thái nổi tiếng với nghề sơn mài, được xác định có mặt từ thế kỷ XVII. Điểm đặc trưng là kỹ thuật sơn mài với các vật liệu truyền thống như sơn cánh gián, sơn then, vỏ trai, vàng thếp, kết hợp kỹ thuật mài để tạo nên tác phẩm độc đáo. Sản phẩm lấy cảm hứng từ thiên nhiên và cảnh vật làng quê Việt Nam', 'mot_nhom_hoi', NULL, 'chi_xem', 'Tổ chức được bất cứ thời gian nào trong năm', 'Dưới 500 người', NULL, '2026-09-21T07:18:32.033Z', '2026-09-21T07:18:32.033Z'),
  ('449d2e8f-2b44-4aa1-9c9c-7f93aafe140d', 'fdd98e46-3b65-490d-aadc-dbb90eab321d', 'Lễ hội làng', NULL, 'Lễ rước kiệu với sự tham gia của các thanh niên độc thân khiêng kiệu; Lễ tế nam và tế nữ riêng biệt; Hát quan họ trên thuyền rồng; Gắn với sự tích bà Đinh Thị Trạch tự nguyện nộp mình cho hổ để cứu dân làng.', 'mot_nhom_hoi', NULL, 'chi_xem', 'Chỉ tổ chức vào 1 thời gian cố định trong năm (9-11/11 âm lịch)', '500 người - 1000 người', NULL, '2026-09-21T07:18:32.033Z', '2026-09-21T07:18:32.033Z'),
  ('c222e4cb-64eb-4d3f-bf02-5f501d5af189', 'fdd98e46-3b65-490d-aadc-dbb90eab321d', 'Tín ngưỡng và tập quán xã hội (Tín ngưỡng thờ mẫu / tín ngưỡng phồn thực / Tín ngưỡng thờ thành hoàng làng / khác )', NULL, 'Thờ hai vị Thành hoàng: Thái sư Bùi Sĩ Lương và bà Đinh Thị Trạch (Bà Lạy). Sự tích bà Lạy tự nguyện hiến thân cho hổ để cứu dân làng là độc đá', 'mot_nhom_hoi', NULL, 'chi_xem', 'Chỉ tổ chức vào 1 thời gian cố định trong năm (9-11/11 âm lịch)', '500 người - 1000 người', NULL, '2026-09-21T07:18:32.033Z', '2026-09-21T07:18:32.033Z'),
  ('3732fc6c-9e37-49c1-8277-7a48ca894740', '09ee09b0-41f2-429c-a515-0cd2592edc44', 'Tín ngưỡng và tập quán xã hội (Tín ngưỡng thờ mẫu / tín ngưỡng phồn thực / Tín ngưỡng thờ thành hoàng làng / khác )', NULL, NULL, 'mot_nhom_hoi', '2 thế hệ (bố mẹ - con cháu) — hơn 3 thế hệ (cụ kị/  tổ tiên - ông bà - bố mẹ -con cháu)', 'chi_xem', 'Tổ chức được bất cứ thời gian nào trong năm', 'Dưới 500 người.', NULL, '2026-09-21T07:18:32.871Z', '2026-09-21T07:18:32.871Z'),
  ('c18d493d-2a0a-47f8-b5ef-865028705418', '09ee09b0-41f2-429c-a515-0cd2592edc44', 'Lễ hội làng Thuận Vi', NULL, 'Tổ chức Hầu bóng (ba sáu giá) từ 10h00 đến 16h00 và tổ chức cho khách thập phương xin xăm (xin thẻ đầu năm cầu may mắn). Lễ rước kiệu, quay kiệu.', 'mot_nhom_hoi', '2 thế hệ (bố mẹ - con cháu) — Hơn 3 thế hệ.', 'chi_xem', 'Chỉ tổ chức vào 1 thời gian cố định trong năm (vd: lễ hội chỉ tổ chức vào 1 vài ngày đầu năm)', 'Dưới 500 người.', NULL, '2026-09-21T07:18:32.871Z', '2026-09-21T07:18:32.871Z'),
  ('e77efb55-f836-4c88-b7a3-7febe2142490', '09ee09b0-41f2-429c-a515-0cd2592edc44', 'Ẩm thực truyền thống (bánh hấp)', NULL, 'Bánh cuốn, bánh hấp, bún chả.', 'mot_nhom_hoi', NULL, 'chi_xem', 'Tổ chức được bất cứ thời gian nào trong năm', '500 người.', NULL, '2026-09-21T07:18:32.871Z', '2026-09-21T07:18:32.871Z'),
  ('ed93388e-ec9a-4454-aa01-bb124ae55452', '09ee09b0-41f2-429c-a515-0cd2592edc44', 'Nghệ thuật trình diễn dân gian (Chèo/ Múa rối nước / quan họ / ca trù / xẩm / khác)', NULL, 'Nghệ thuật trình diễn nón lá ở làng Chuông thể hiện qua quá trình chế tác thủ công của người thợ với các công đoạn tỉ mỉ như xử lý lá, tạo khung, xếp lá và khâu nón. Điểm đặc trưng nằm ở sự khéo léo, kỹ thuật truyền đời và không gian trình diễn gắn với làng nghề, giúp du khách cảm nhận được giá trị văn hóa của chiếc nón lá và nghề thủ công truyền thống.', 'mot_nhom_hoi', '2 thế hệ (bố mẹ - con cháu) — hơn 3 thế hệ (cụ kị/  tổ tiên - ông bà - bố mẹ -con cháu)', 'chi_xem', 'Chỉ tổ chức vào 1 thời gian cố định trong năm (vd: lễ hội chỉ tổ chức vào 1 vài ngày đầu năm)', 'Dưới  500 người.', NULL, '2026-09-21T07:18:32.871Z', '2026-09-21T07:18:32.871Z'),
  ('071da456-4608-49cf-b1b1-e6edaab0c749', 'c33319de-4845-41bf-94c1-3fa501e5e867', 'Lễ hội làng Cựu  (Lễ hội Thành Hoàng Làng Cựu)', NULL, 'Nghề may – nghề đã làm nên tên tuổi và sự phồn thịnh của ngôi làng từ đầu thế kỷ XX. Không chỉ là dịp thực hành tín ngưỡng thờ Thành hoàng, lễ hội còn là dịp để con cháu làm nghề may trở về quê hương, tưởng nhớ tổ tiên và gìn giữ bản sắc làng nghề. Sự kết hợp giữa lễ hội truyền thống, nghề may lâu đời và không gian làng cổ đã tạo nên dấu ấn riêng của Làng Cựu.', 'mot_nhom_hoi', '2 thế hệ (bố mẹ - con cháu) — Được truyền đời từ xưa đến nay.', 'chi_xem', 'Diễn ra trong 3 ngày, bắt đầu từ ngày mùng 7 đến mùng 9 tháng Giêng âm lịch hàng năm.', 'Dưới 500 người.', NULL, '2026-09-21T07:18:33.530Z', '2026-09-21T07:18:33.530Z'),
  ('3ea871c6-5864-4b84-84bc-2beca400d2a1', 'c33319de-4845-41bf-94c1-3fa501e5e867', 'Tri thức dân gian (nghề thuốc, chữa bệnh, may đo trang phục…)', NULL, 'Nghề may Làng Cựu mang nét đặc trưng riêng bởi đây không chỉ là một nghề thủ công truyền thống mà còn gắn liền với quá trình hình thành và phát triển của cả cộng đồng cư dân. Từ đầu thế kỷ XX, nhiều người dân trong làng trở thành những thợ may nổi tiếng tại Hà Nội, phục vụ nhu cầu may đo cao cấp, đặc biệt là comple, veston. Sự phát triển của nghề may đã tạo nên sự thịnh vượng cho làng, làm thay đổi diện mạo không gian cư trú với những công trình kiến trúc mang dấu ấn giao thoa Việt – Pháp. Điểm đặc biệt của Làng Cựu nằm ở sự kết hợp giữa tay nghề may thủ công tinh tế, truyền thống làng nghề lâu đời và giá trị kiến trúc – văn hóa được hình thành từ chính nghề nghiệp của người dân.', NULL, '2 thế hệ (bố mẹ - con cháu) — Hơn 3 thế hệ.', 'chi_xem', 'Tổ chức bất cứ lúc nào trong năm.', 'Dưới 500 người.', NULL, '2026-09-21T07:18:33.530Z', '2026-09-21T07:18:33.530Z'),
  ('85e1349c-c7eb-4861-ba94-1f643b13d39b', 'c33319de-4845-41bf-94c1-3fa501e5e867', 'Ẩm thực truyền thống (bánh cuốn)', NULL, 'Đặc trưng nằm ở cách làm thủ công, sự khéo léo trong tráng bánh, pha nước chấm và chuẩn bị nhân, phản ánh sự tinh tế của văn hóa ẩm thực Bắc Bộ.', NULL, '2 thế hệ (bố mẹ - con cháu) — Được truyền lại đến nay.', NULL, NULL, NULL, NULL, '2026-09-21T07:18:33.530Z', '2026-09-21T07:18:33.530Z'),
  ('e61abaa5-19a3-43c7-ba7a-9353fe67520a', 'c33319de-4845-41bf-94c1-3fa501e5e867', 'Trò chơi dân gian', NULL, NULL, 'mot_nhom_hoi', '2 thế hệ (bố mẹ - con cháu) — Hơn 3 thế hệ.', 'chi_xem', 'Chỉ tổ chức vào ngày hội của làng.', 'Dưới 500 người.', NULL, '2026-09-21T07:18:33.530Z', '2026-09-21T07:18:33.530Z'),
  ('5c452674-fdb7-44ba-9532-9ab2982c27ee', '8216fe86-f66d-4b19-904b-cbdee0bf1eba', 'Lễ hội làng Đồng Trữ', NULL, 'Tổ chức ngày 16 và ngày 17/3 (tức ngày 11 và 12/2 năm Kỷ Hợi)
lễ hội Quán Bà - thôn Đồi Chè, xã Thanh Bình được tổ chức ngày 18 và 19/3 (tức ngày 13 và 14/2 năm Kỷ Hợi) nhằm tưởng nhớ công lao to lớn của các vị Thành Hoàng làng. Cả hai lễ hội truyền thống đều diễn ra với chương trình đó là:  phần lễ gồm tế lễ, dâng hương và rước kiệu truyền thống. Phần hội diễn ra các hoạt động như: giao lưu văn hóa văn nghệ, các trò chơi dân gian...', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-21T07:18:34.352Z', '2026-09-21T07:18:34.352Z'),
  ('853fa527-b187-4f8b-9941-82b0183bcc93', '8216fe86-f66d-4b19-904b-cbdee0bf1eba', 'Tri thức dân gian (Nghề truyền thống)', NULL, 'Làng nghề duy nhất ở Việt Nam có kỹ thuật xâu xiên sử dụng sợ Mây. Đây là kỹ thuật đỉnh cao của nghệ thuật đan lát Việt Nam. Được làm thủ công từ đôi bàn tay khéo léo, được chăm chút bằng trái tim yêu nghề say nghề, mỗi sản phẩm mây tre đan Phú Vinh đều mang trên mình dấu ấn của cá nhân người nghệ nhân, dấu ấn của quê hương và cả hơi thở của thời đại. Từ cái nơm cái vó, cái mủng cái giỏ xưa kia, vẫn bằng kỹ thuật đan lát được truyền từ đời này qua đời khác nhưng nhờ sự sáng tạo của các nghệ nhân, bình hoa, lót cốc, cái khay, chiếc ghế với nhiều hoa văn đẹp mắt đã ra đời phục vụ nhu cầu của người dân. Kết quả lao động sáng tạo ấy đã giúp nhiều gia đình, nhiều thế hệ người làng trụ được với nghề truyền thống.', NULL, 'hơn 3 thế hệ (cụ kị/  tổ tiên - ông bà - bố mẹ -con cháu) — Hơn 3 thế hệ', 'trai_nghiem_toan_bo', 'Bất cứ thời gian nào', 'Dưới 500 người', NULL, '2026-09-21T07:18:34.352Z', '2026-09-21T07:18:34.352Z'),
  ('f80025b2-f08d-4752-966f-44c1aa0badd6', '8216fe86-f66d-4b19-904b-cbdee0bf1eba', 'Ẩm thực truyền thống (bánh cuốn, bánh đúc)', NULL, 'Làng Phú Vinh có món
bánh cuốn ngon nổi tiếng trong vùng. Theo Nguyễn Văn Trung – Trước đây từng là chủ nhiệm CLB nghệ nhân; hiện nay chỉ dạy nghề chứ không sản xuất, thì món bánh cuốn làng Phú Vinh được nhiều người dân trong ngoài làng cũng như du khách ưa thích. Ngoài ra ở chợ Chuông còn có món bánh đúc lạc cũng được bày bán thường xuyên trong các phiên chợ và là một món ăn dân dã gắn bó với cuộc sống người nông dân.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-21T07:18:34.352Z', '2026-09-21T07:18:34.352Z'),
  ('9397e3f7-6cda-4c63-a35a-84aafb1ca11c', '00000000-0000-0000-0000-000000000001', 'Lễ hội ăn Tết bù', NULL, 'Cứ vào ngày Rằm tháng Giêng hàng năm, trong khi người dân khắp mọi miền nô nức lễ chùa thì làng giò chả Ước Lễ lại rộn ràng ăn Tết trở lại. Đặc biệt, ở làng Ước Lễ có một tục lệ “bất thành văn” là những người con xa quê hương dù ở mọi miền đất nước và có bận trăm công ngàn việc cũng sắp xếp về sum họp cùng gia đình, bà con dân làng. Theo nghi lễ của làng, sau khi làm lễ cúng gia tiên xong, người dân làng Ước Lễ súng sính quần áo lên chùa dự hội, xin lộc hoặc đến các gia đình hàng xóm để gặp mặt nhau và chúc Tết cho nhau những điều tốt đẹp nhất.', 'toan_the_cong_dong', NULL, 'trai_nghiem_toan_bo', 'Rằm tháng Giêng', 'chia về ăn cỗ ở các nhà dân', NULL, '2026-09-21T07:18:35.222Z', '2026-09-21T07:18:35.222Z'),
  ('b7010a01-e06c-4ac2-9bea-7e7c5e04158a', '00000000-0000-0000-0000-000000000001', 'Ẩm thực truyền thống: giò chả', 'quoc_gia', 'Làm từ thịt lợn tươi, còn nóng, với các khâu lọc, xay, gói. Gói giò bằng lá chuối, để giò thơm ngon, dậy mùi. Lá chuối cũng phải chọn kỹ, lá nõn lần trong, lá bánh tẻ lần giữa, lá già lần ngoài. Giò gói xong đem thả ngay vào nồi nước sôi và luộc, tùy theo cỡ giò mà có thời gian vớt thích hợp. Giò thành phẩm mịn, nhẵn có màu hồng nhạt, ăn phải giòn, còn thơm mùi thịt, miếng giò cắt ra phải có những lỗ nhỏ… mới là giò ngon. Miếng giò mượt như lụa nên được gọi tên là giò lụa', 'toan_the_cong_dong', 'hơn 3 thế hệ (cụ kị/  tổ tiên - ông bà - bố mẹ -con cháu) — hơn 500 năm', 'trai_nghiem_toan_bo', 'Tổ chức hàng tuần vào thứ 5, thứ 7 hoặc khi có đoàn đăng ký', NULL, NULL, '2026-09-21T07:18:35.222Z', '2026-09-21T07:18:35.222Z'),
  ('d5fa2839-2491-425d-bb65-dc108cee8575', '00000000-0000-0000-0000-000000000001', 'Lễ hội làng', NULL, 'Ngày 12/3 và 12/8 là ngày kỳ phước, giỗ Thành hoàng làng: 12/3 cúng thịt thủ tại đình; ngày 12/8 thì làm thịt bò thui trấu, là ngày lễ đặc biệt trong làng. Thường có khoảng 160-170 mâm tại Đình', 'toan_the_cong_dong', NULL, NULL, '12/3 và 12/8 âm lịch', NULL, NULL, '2026-09-21T07:18:35.222Z', '2026-09-21T07:18:35.222Z')
